use super::dcd::{CheckCond, Dcd, DcdCommand, DcdError, RegisterWrite, Width, WriteOp};

const fn w(address: u32, value: u32) -> RegisterWrite {
    RegisterWrite { address, value }
}

/// SEMC_INTR: bit 0 IPCMDDONE.
const SEMC_INTR: u32 = 0x402F_003C;

const fn write(writes: &[RegisterWrite]) -> DcdCommand<'_> {
    DcdCommand::Write {
        op: WriteOp::Write,
        width: Width::Word,
        writes,
    }
}

/// Wait for the SEMC IP command to finish (IPCMDDONE).
const WAIT_IPCMD_DONE: DcdCommand<'static> = DcdCommand::Check {
    cond: CheckCond::AnySet,
    width: Width::Word,
    address: SEMC_INTR,
    mask: 0x1,
    count: None,
};

