/// IP command AUTO REFRESH (command 0xC).
const AUTO_REFRESH_1: [RegisterWrite; 2] = [
    w(0x402F0090, 0x80000000), // SEMC_IPCR0
    w(0x402F009C, 0xA55A000C), // SEMC_IPCMD
];

/// IP command AUTO REFRESH again (command 0xC).
const AUTO_REFRESH_2: [RegisterWrite; 2] = [
    w(0x402F0090, 0x80000000), // SEMC_IPCR0
    w(0x402F009C, 0xA55A000C), // SEMC_IPCMD
];

/// IP command MODE SET (command 0xA) with mode register 0x30 from
/// IPTXDAT: CAS latency 3, burst length 1.
const MODE_SET: [RegisterWrite; 3] = [
    w(0x402F00A0, 0x00000030), // SEMC_IPTXDAT
    w(0x402F0090, 0x80000000), // SEMC_IPCR0
    w(0x402F009C, 0xA55A000A), // SEMC_IPCMD
];

/// SDRAMCR3 again with REN (bit 0) set: auto refresh on.
const REFRESH_ENABLE: [RegisterWrite; 1] = [
    w(0x402F004C, 0x50210A09), // SEMC_SDRAMCR3
];

/// The SDK's command list.
pub const COMMANDS: [DcdCommand<'static>; 9] = [
    write(&SETUP_AND_PRECHARGE),
    WAIT_IPCMD_DONE,
    write(&AUTO_REFRESH_1),
    WAIT_IPCMD_DONE,
    write(&AUTO_REFRESH_2),
    WAIT_IPCMD_DONE,
    write(&MODE_SET),
    WAIT_IPCMD_DONE,
    write(&REFRESH_ENABLE),
];

/// The EVKB SDRAM DCD, encoded.
pub fn dcd() -> Result<Dcd, DcdError> {
    Dcd::encode(&COMMANDS)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rt2_dcd_is_the_sdk_sdram_setup() {
        let sdk = include_bytes!("../../fixtures/evkbimxrt1050-dcd.bin");
        let Ok(dcd) = dcd() else {
            panic!("the SDK DCD encodes")
        };
        assert_eq!(dcd.len(), 0x410);
        assert_eq!(dcd.as_bytes(), &sdk[..]);
    }

    #[test]
    fn rt2_dcd_maps_sdram_at_0x8000_0000() {
        let br0 = SETUP_AND_PRECHARGE
            .iter()
            .find(|w| w.address == 0x402F_0010);
        assert_eq!(br0.map(|w| w.value), Some(0x8000_001B));
        // MODE SET writes mode register 0x30 (CL 3, burst 1).
        assert_eq!(MODE_SET[0], w(0x402F_00A0, 0x30));
        assert_eq!(REFRESH_ENABLE[0].value & 1, 1);
    }
}
